-- PCMT Fantasy Decks: cards, card packs and buying packs with VP.
-- Paste this whole file into Supabase → SQL Editor → New query → Run. Safe to run more than once.
-- Needs setup/vp-setup.sql first (VP ledger and admins). This file is generated by tools/cards.py.
--
-- How it works:
--   * cards: every card that exists. Each store player is a Common card; variants (special art) have a rarity.
--   * card_packs: packs for sale (an NA pack and an EMEA pack, each drawing only that region's players), with price (set on backend.html, Card packs tab), cards per pack and odds per card.
--   * Throwback packs: one per past season (S1 NA, S2 NA, S1 EMEA). A pack with a season only draws that season's cards;
--     the NA and EMEA packs (no season) only draw this season's cards. Past-season cards are not on The Deck.
--   * buy_pack(pack): the only way to buy. It runs on the server: checks the price and the buyer's VP,
--     takes the VP, draws the cards with the odds, and saves them. Nothing in the browser can pick cards.
--   * If a drawn rarity has no cards yet (e.g. no Legendary cards exist), the card drops to the next tier down.
--   * Duplicates are kept: user_cards counts how many of each card a player owns.
--   * Until a pack is opened to everyone (open_to_all on backend.html), only admins and PCMT Team staff can buy it, to test.

-- ===================== Tables =====================
create table if not exists public.cards (
  id text primary key,                      -- 'c:<player id>' for a normal card, 'v:<variant id>' for a variant
  player text not null,                     -- player id from players.js
  variant text,                             -- null for a normal card
  rarity text not null check (rarity in ('common', 'rare', 'epic', 'legendary')),
  title text not null,
  region text not null default 'NA' check (region in ('NA', 'EMEA')),
  season text,                              -- null = this season; 'S1 NA' etc. for a past-season card (player = its MVP VS card id)
  active boolean not null default true      -- switched off instead of deleted, so owned cards stay valid
);
alter table public.cards add column if not exists region text not null default 'NA' check (region in ('NA', 'EMEA'));
alter table public.cards add column if not exists season text;
-- released: only released cards can be pulled from packs. Commons are always released; Rare (and up) cards start
-- unreleased and are released one by one by PCMT Team staff on backend.html (Rare cards tab).
do $$ begin
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'cards' and column_name = 'released') then
    alter table public.cards add column released boolean not null default false;
    update public.cards set released = (rarity = 'common');
  end if;
end $$;
alter table public.cards enable row level security;
drop policy if exists "anyone can read cards" on public.cards;
create policy "anyone can read cards" on public.cards for select using (true);

create table if not exists public.card_packs (
  id text primary key,
  name text not null,
  region text not null default 'NA' check (region in ('NA', 'EMEA')),   -- the pack only draws cards from this region
  season text,                              -- null = this season's cards; 'S1 NA' etc. = a throwback pack for that season
  cards integer not null default 5 check (cards between 1 and 10),
  odds jsonb not null,                      -- percent per card, e.g. {"common":70,"rare":22,"epic":7,"legendary":1}
  price integer check (price >= 0),         -- VP; null = not priced yet, can't be bought
  active boolean not null default true,
  open_to_all boolean not null default false
);
alter table public.card_packs add column if not exists region text not null default 'NA' check (region in ('NA', 'EMEA'));
alter table public.card_packs add column if not exists season text;
alter table public.card_packs enable row level security;
drop policy if exists "anyone can read packs" on public.card_packs;
create policy "anyone can read packs" on public.card_packs for select using (true);
drop policy if exists "admins change packs" on public.card_packs;
create policy "admins change packs" on public.card_packs for update
  using (exists (select 1 from public.pcmt_admins a where a.user_id = auth.uid()) or public.is_freshbatch())
  with check (exists (select 1 from public.pcmt_admins a where a.user_id = auth.uid()) or public.is_freshbatch());

create table if not exists public.user_cards (
  user_id uuid not null references auth.users (id) on delete cascade,
  card_id text not null references public.cards (id),
  count integer not null default 1 check (count > 0),
  first_at timestamptz not null default now(),
  primary key (user_id, card_id)
);
alter table public.user_cards enable row level security;
drop policy if exists "read own cards" on public.user_cards;
create policy "read own cards" on public.user_cards for select using (auth.uid() = user_id);
-- in_deck: a Rare (or up) the player picked on the Library page for their MVP VS deck. Set only with set_card_in_deck().
alter table public.user_cards add column if not exists in_deck boolean not null default false;

create table if not exists public.pack_openings (
  id bigserial primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  pack text not null,
  price integer not null,
  cards jsonb not null,
  created_at timestamptz not null default now()
);
create index if not exists pack_openings_user on public.pack_openings (user_id, created_at);
alter table public.pack_openings enable row level security;
drop policy if exists "read own openings" on public.pack_openings;
create policy "read own openings" on public.pack_openings for select using (auth.uid() = user_id);
-- No insert/update/delete policies on user_cards or pack_openings: only buy_pack writes them.

-- ===================== Buying =====================
create or replace function public.buy_pack(p_pack text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  u uuid := auth.uid(); pk record; bal int; total numeric; roll numeric; acc numeric;
  tiers text[] := array['common', 'rare', 'epic', 'legendary']; drawn text; got_tier text; idx int;
  c record; n int; out jsonb := '[]'::jsonb; i int;
begin
  if u is null then raise exception 'Log in with Discord to buy packs.'; end if;
  perform pg_advisory_xact_lock(hashtext('pcmt-buy:' || u::text));    -- one purchase at a time per player
  select * into pk from public.card_packs where id = p_pack;
  if not found or not pk.active then raise exception 'That pack isn''t for sale.'; end if;
  if not pk.open_to_all and not exists (select 1 from public.pcmt_admins a where a.user_id = u) and not public.is_freshbatch() then
    raise exception 'Packs aren''t on sale yet.';
  end if;
  if pk.price is null then raise exception 'This pack doesn''t have a price yet.'; end if;
  select coalesce(sum(amount), 0)::int into bal from public.vp_ledger where user_id = u;
  if bal < pk.price then raise exception 'Not enough Credits: this pack costs % Credits and you have %.', pk.price, bal; end if;
  if pk.price > 0 then
  end if;

  select sum(greatest(0, coalesce((pk.odds ->> t)::numeric, 0))) into total from unnest(tiers) t;
  if total is null or total <= 0 then raise exception 'This pack has no odds set.'; end if;
  for i in 1 .. pk.cards loop
    roll := random() * total; acc := 0; drawn := 'common';
    foreach drawn in array tiers loop
      acc := acc + greatest(0, coalesce((pk.odds ->> drawn)::numeric, 0));
      exit when roll < acc;
    end loop;
    got_tier := drawn;
    -- No released cards of that rarity in this pack yet: a Common instead (Nov 5 2026; it used to be the tier below,
    -- which turned Legendary rolls into extra Rares in packs with no Legendary).
    if got_tier <> 'common' and not exists (select 1 from public.cards where active and released and region = pk.region and season is not distinct from pk.season and rarity = got_tier) then
      got_tier := 'common';
    end if;
    select * into c from public.cards where active and released and region = pk.region and season is not distinct from pk.season and rarity = got_tier order by random() limit 1;
    if not found then raise exception 'There are no cards to draw yet.'; end if;
      on conflict (user_id, card_id) do update set count = public.user_cards.count + 1
      returning count into n;
    out := out || jsonb_build_array(jsonb_build_object('id', c.id, 'player', c.player, 'variant', c.variant, 'rarity', c.rarity,
                                                       'title', c.title, 'region', c.region, 'season', c.season, 'count', n, 'new', n = 1));
  end loop;
  -- Shuffle the order so a rare can be anywhere in the pack (each card is drawn on its own, this just mixes the reveal order),
  -- except that a Legendary always comes last: the pack opening reveals the cards in this order.
  select coalesce(jsonb_agg(x order by (x ->> 'rarity') = 'legendary', random()), '[]'::jsonb) into out from jsonb_array_elements(out) x;
  return jsonb_build_object('pack', pk.name, 'price', pk.price, 'balance', bal - pk.price, 'cards', out);
end $$;
revoke all on function public.buy_pack(text) from public, anon;
grant execute on function public.buy_pack(text) to authenticated;

-- Release (or hold back) a Rare-or-up card: PCMT Team staff only, from backend.html. Commons are always released.
create or replace function public.fb_release_card(p_card text, p_released boolean) returns boolean
language plpgsql security definer set search_path = public as $$
declare r text;
begin
  if not public.is_freshbatch() then raise exception 'PCMT Team staff only.'; end if;
  select rarity into r from public.cards where id = p_card;
  if r is null then raise exception 'No card %.', p_card; end if;
  if r = 'common' then raise exception 'Common cards are always released.'; end if;
  update public.cards set released = coalesce(p_released, false) where id = p_card;
  return coalesce(p_released, false);
end $$;
revoke all on function public.fb_release_card(text, boolean) from public, anon;
grant execute on function public.fb_release_card(text, boolean) to authenticated;

-- Put an owned Rare-or-up card in (or take it out of) your MVP VS deck, from the Library page.
create or replace function public.set_card_in_deck(p_card text, p_on boolean) returns boolean
language plpgsql security definer set search_path = public as $$
declare u uuid := auth.uid(); r text;
begin
  if u is null then raise exception 'Log in with Discord first.'; end if;
  select c.rarity into r from public.user_cards uc join public.cards c on c.id = uc.card_id where uc.user_id = u and uc.card_id = p_card;
  if r is null then raise exception 'You don''t own that card.'; end if;
  if r = 'common' then raise exception 'Only Rare cards (or rarer) go in your MVP VS deck.'; end if;
  update public.user_cards set in_deck = coalesce(p_on, false) where user_id = u and card_id = p_card;
  return coalesce(p_on, false);
end $$;
revoke all on function public.set_card_in_deck(text, boolean) from public, anon;
grant execute on function public.set_card_in_deck(text, boolean) to authenticated;

